function validateOption(key,v){const t=state().options.term.value;if(key==='term'&&v.type==='indefinite'&&(!Number.isInteger(v.noticeMonths)||v.noticeMonths<1||v.noticeMonths>120||!v.terminationRule?.trim()))return 'Bei unbefristeter Dauer sind Kündigungsfrist und Kündigungsregel Pflicht.';if(key==='term'&&v.type==='fixed'&&v.end<=v.start)return 'Das Vertragsende muss nach dem Mietbeginn liegen.';if(key==='extension'&&t.type!=='fixed')return 'Die Verlängerungsoption setzt eine feste Vertragsdauer voraus.';if(key==='break'&&v.enabled&&(v.earliest<=t.start||(t.type==='fixed'&&v.earliest>=t.end)))return 'Der vorzeitige Beendigungstermin muss nach Mietbeginn und vor dem festen Vertragsende liegen.';return '';}
