  if(!unlimited&&m!=='date'){const n=custom?Number(e.years.value):Number(m);if(e.start.value&&Number.isInteger(n)&&n>=1&&n<=100){const [y,mo,day]=e.start.value.split('-').map(Number),end=new Date(Date.UTC(y+n,mo-1,day));end.setUTCDate(end.getUTCDate()-1);e.end.value=end.toISOString().slice(0,10);}}
