 form.oninput=()=>{update();d.draft=read();};form.onchange=()=>{update();d.draft=read();};update();
 form.onsubmit=e=>{e.preventDefault();const next=read(),error=validateOption('term',next);if(error){detail.querySelector('#lc-term-error').textContent=error;return;}if(isManager)applyOption('term',next);else{d.proposal=next;d.draft=null;d.log='Mieterseite · Vorschlag eingereicht';}render();};
